<script lang="ts">
  import {segmentAssignment} from '#lib/client/time-allocation.ts';
  import {scrollRegion} from '#lib/client/scroll-region.ts';
  import type {AppData,Row} from '#lib/client/types.ts';import {display,displayTimestamp} from '#lib/client/api.ts';
  let {snapshot={},data}:{snapshot?:Row;data:AppData}=$props();
  const intervals=$derived([...(snapshot.segments||snapshot.allocations||[])].sort((a,b)=>Date.parse(a.started_at||a.start_at)-Date.parse(b.started_at||b.start_at)));
  function order(interval:Row){if(interval.kind==='break')return '—';if(interval.order_id)return display(interval.order_id,'order_id',data);const assignment=segmentAssignment(interval,snapshot.allocations||[]);return assignment.multiple?'Mehrere Zuordnungen':assignment.order_id?display(assignment.order_id,'order_id',data):assignment.assigned?'Betriebliche Arbeit · ohne Auftrag':'Zuordnung prüfen';}
</script>
<div class="time-snapshot">
  {#if snapshot.session}<dl><div><dt>Beginn</dt><dd>{displayTimestamp(snapshot.session.started_at)}</dd></div><div><dt>Ende</dt><dd>{displayTimestamp(snapshot.session.ended_at)}</dd></div></dl>{/if}
  {#if intervals.length}<div class="table-scroll desktop-only" use:scrollRegion={'Zeitnachweis'}><table class="data-table"><thead><tr><th>Art</th><th>Beginn</th><th>Ende</th><th>Auftrag</th></tr></thead><tbody>{#each intervals as interval}<tr><td>{interval.kind==='break'?'Pause':'Arbeit'}</td><td>{displayTimestamp(interval.started_at||interval.start_at)}</td><td>{displayTimestamp(interval.ended_at||interval.end_at)}</td><td>{order(interval)}</td></tr>{/each}</tbody></table></div>{:else}<p class="small">Für diesen Stand liegen keine bestätigten Intervalle vor.{snapshot.conflicts?.length?` ${snapshot.conflicts.length} Originalaufzeichnung(en) sind als Konfliktnachweis erhalten.`:''}</p>{/if}
<div class="mobile-only">{#each intervals as interval}<article class="proof-card"><h3>{interval.kind==='break'?'Pause':'Arbeit'} · {order(interval)}</h3><dl><div><dt>Von</dt><dd>{displayTimestamp(interval.started_at||interval.start_at)}</dd></div><div><dt>Bis</dt><dd>{interval.ended_at||interval.end_at?displayTimestamp(interval.ended_at||interval.end_at):'Läuft'}</dd></div></dl>{#if interval.activity}<p>{display(interval.activity,'activity')}</p>{/if}</article>{/each}</div>
<div class="mt">{#if snapshot.allocations?.length}<h3 style="font-size:13px;font-weight:500;margin-bottom:12px">Tatsächliche Arbeitszuordnung</h3><div class="mobile-only">{#each snapshot.allocations as allocation}<article class="proof-card"><h3>{allocation.order_id?display(allocation.order_id,'order_id',data):'Betriebliche Arbeit · ohne Auftrag'}</h3><p>{display(allocation.activity,'activity')}</p><p>{displayTimestamp(allocation.started_at)} – {allocation.ended_at?displayTimestamp(allocation.ended_at):'Läuft'}</p></article>{/each}</div><div class="table-scroll desktop-only" use:scrollRegion={'Zeitnachweis'}><table class="data-table"><thead><tr><th>Von</th><th>Bis</th><th>Auftrag</th><th>Tätigkeit</th></tr></thead><tbody>{#each [...snapshot.allocations].sort((a,b)=>Date.parse(a.started_at)-Date.parse(b.started_at)) as allocation}<tr><td>{displayTimestamp(allocation.started_at)}</td><td>{displayTimestamp(allocation.ended_at)}</td><td>{allocation.order_id?display(allocation.order_id,'order_id',data):'Betriebliche Arbeit · ohne Auftrag'}</td><td>{allocation.activity?display(allocation.activity,'activity'):'Nicht angegeben'}</td></tr>{/each}</tbody></table></div>{/if}</div>
  <div class="mt"><p class="field-help">Tätigkeit: {snapshot.session?.current_activity||snapshot.activity||snapshot.allocations?.map((a:Row)=>a.activity).filter(Boolean).join(' · ')||'In den Zuordnungen angegeben'}</p>{#if snapshot.session?.notes||snapshot.reason}<p class="small mt"><strong>Anlass / Hinweis:</strong> {snapshot.session?.notes||snapshot.reason}</p>{/if}<p class="field-help mt">{intervals.length} {intervals.length===1?'Intervall':'Intervalle'} · {snapshot.allocations?.length??0} {snapshot.allocations?.length===1?'Arbeitszuordnung':'Arbeitszuordnungen'}. Originalstände und geprüfte Korrekturen bleiben getrennt erhalten.</p></div>
</div>
<style>.proof-card{padding:12px 0;border-top:1px solid var(--line)}.proof-card h3{font-size:13px;line-height:1.5;font-weight:550}.proof-card p{font-size:12px;margin-top:7px;line-height:1.6}.proof-card dl{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:10px 0 0}.proof-card dd{font-size:12px;line-height:1.6;word-break:normal;overflow-wrap:normal}.time-snapshot{border:1px solid var(--line);border-radius:10px;padding:17px;min-width:0}.time-snapshot dl{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:0 0 18px}dt{font-size:12px;color:var(--muted);margin-bottom:5px}dd{font-size:14px;margin:0}</style>
